mutation ChangeCaseData($input: ChangeCaseDataInput!) {
  dispatch {
    changeCaseData(input: $input) {
      externalId
      metadataId
      workQueueId
      output {
        runId
        change
      }
    }
  }
}

query DecisionJournal($input: DecisionJournalInput!) {
  discover {
    decisionJournal(input: $input) {
      runId
      replayDecisionsOf
      replayAbandoned
      decisions {
        questionKey
        occurrence
        kind
        replayed
        replayRefused
        model
        decider
        question
        answer
        stateHash
        decidedAt
      }
    }
  }
}

mutation OrderTrouble($input: OrderTroubleInput!) {
  dispatch {
    orderTrouble(input: $input) {
      externalId
      metadataId
      workQueueId
      output {
        trouble
      }
    }
  }
}

query OrdersTabletCalls {
  discover {
    orders {
      tabletCalls {
        restaurant
        calls {
          orderId
          attempt
          startedAt
          endedAt
          problem
        }
      }
    }
  }
}

mutation StartRun($input: StartRunInput!) {
  dispatch {
    startRun(input: $input) {
      externalId
      metadataId
      workQueueId
      output {
        runId
        manifestId
        manifestExternalId
        trainName
        armedCrash
        maxRetries
        firstRunId
      }
    }
  }
}
